Problem Description:
Implement a D latch using an always block.

module top_module (
	input d,
	input ena,
	output logic q
);

Erroneous Implementation:

always_ff @(posedge clk or posedge reset)
begin
	if (reset)
		q <= 1'b0;
	else if (ena)
		q <= d;
end

endmodule

